var stdout = (msg.payload || '').trim();
var comments = [];
if (stdout !== '') {
    try {
        comments = JSON.parse(stdout);
    } catch (e) {
        node.error('Error parsing comments JSON: ' + e.message);
    }
}
msg.comments = comments;
return msg;

var role = 'dev';
if (msg.assigneeID === 3) role = 'tester';
else if (msg.assigneeID === 4) role = 'boss';
else if (msg.assigneeID === 5) role = 'lead';

msg.template_path = 'cmd/build/templates/' + role + '.md';
msg.payload = 'cat ' + msg.template_path;
return msg;

var template = msg.payload || '';
var task = msg.task;
var comments = msg.comments || [];

var commentsHistory = '';
if (comments.length > 0) {
    for (var i = 0; i < comments.length; i++) {
        commentsHistory += comments[i].role + ': ' + comments[i].content + '\n----------------------------------------\n';
    }
} else {
    commentsHistory = '(No comments yet)';
}

var contextContent = '\n\n---\n### YOUR CURRENT ASSIGNMENT\nTask ID: ' + task.id + '\nTitle: ' + task.title + '\nDescription: ' + (task.description || '') + '\n\n### COMMENTS HISTORY\n' + commentsHistory + '\n';

msg.agentPrompt = template + contextContent;

// Write to file inside Node-RED using inline node function (since fs is available, or write command)
// To be extremely robust, we will write the instructions file via standard echo/printf or node-red write
// We'll construct a shell command that writes the prompt safely, or writes it using sqlite or standard CLI
// Let's create a temporary file name:
var filepath = '.build/agent_' + msg.assigneeID + '.md';
msg.agentFile = filepath;

// We will write this prompt using fs inside Node-RED if we can, or construct an exec command
// Let's write the command to write the file, then execute the agent, then clean up!
// We will use standard cat and EOF to write to file safely in msg.payload
msg.payload = 'cat << \'EOF\' > ' + filepath + '\n' + msg.agentPrompt + '\nEOF\n' + 'agent ' + msg.adapter + ' < ' + filepath + '; rm -f ' + filepath;

return msg;
